    [GenericTypeArguments(typeof(string))]
    [GenericTypeArguments(typeof(int))]
    [GenericTypeArguments(typeof(bool))]
    public class PolymorphicArrays<T>
    {
        private T[] _largeArray_normal;
        private object[] _largeArray_polymorphic;
        private string _json;

        [GlobalSetup]
        public void Setup()
        {
            const int Length = 1000;

            _largeArray_normal = new T[Length];
            _largeArray_polymorphic = new object[Length];

            if (_largeArray_normal is string[] stringArray)
            {
                for (int i = 0; i < Length; i++)
                {
                    stringArray[i] = i.ToString();
                }
            }
            else if (_largeArray_normal is int[] intArray)
            {
                for (int i = 0; i < Length; i++)
                {
                    intArray[i] = i;
                }
            }
            else if (_largeArray_normal is bool[] boolArray)
            {
                for (int i = 0; i < Length; i++)
                {
                    boolArray[i] = ((i & 1) == 1);
                }
            }

            for (int i = 0; i < Length; i++)
            {
                _largeArray_polymorphic[i] = _largeArray_normal[i];
            }

            _json = JsonSerializer.Serialize(_largeArray_normal);

            string json = JsonSerializer.Serialize(_largeArray_polymorphic);
            if (json != _json)
            {
                throw new InvalidOperationException("Json should match.");
            }
        }

        [BenchmarkCategory(Categories.Libraries, Categories.JSON)]
        [Benchmark]
        public string Serialize_LargeArray_Baseline() => JsonSerializer.Serialize(_largeArray_normal);

        [BenchmarkCategory(Categories.Libraries, Categories.JSON)]
        [Benchmark]
        public string Serialize_LargeArray_Polymorphic() => JsonSerializer.Serialize(_largeArray_polymorphic);

        [BenchmarkCategory(Categories.Libraries, Categories.JSON)]
        [Benchmark]
        public T[] Deserialize_LargeArray_Baseline() => JsonSerializer.Deserialize<T[]>(_json);

        [BenchmarkCategory(Categories.Libraries, Categories.JSON)]
        [Benchmark]
        public object[] Deserialize_LargeArray_Polymorphic() => JsonSerializer.Deserialize<object[]>(_json);
    }

